def r2(seed, dtype, B):
    if seed % 3 == 1:
        return (
            torch.tensor(random.uniform(-1, 1), dtype=dtype)
            .detach()
            .requires_grad_(True)
        )
    else:
        return (torch.rand(B, 1, dtype=dtype) * 2 - 1).detach().requires_grad_(True)

def b(seed, k):
    b = torch.empty(100, 10, dtype=k.dtype).normal_(-1, 1)
    b /= b.norm(dim=-1, keepdim=True)
    b *= (torch.rand_like(k) * k) ** 0.5
    return lorentz.math.project(b, k=k)

