def parse_rows_output():
    def _output_list(data, type):
        rows = []
        for index, line in enumerate(data.split('\n')):
            if all(
                    s not in line for s in ('----', '====')
            ) and line and index != 1:
                rows.append(Row(line, type))
        return rows

    return _output_list

