def call_data(etcdctl_path, tmp_path):
    res = {}
    base_args = [
        str(etcdctl_path),
        "--endpoints",
        "http://127.0.0.1:2379",
    ]

    for user in ["root", "calico", "adminrouter"]:
        tmp_args = base_args + ["user", "add", "--no-password", user]
        res["user_add_" + user] = {
            "args":
            tmp_args,
            "action":
            subprocess.CompletedProcess(
                args=tmp_args,
                returncode=0,
                stdout=b'',
                stderr=b'',
            )
        }

    for role in ["calico_prefix", "adminrouter_prefix"]:
        tmp_args = base_args + ["role", "add", role]
        res["role_add_" + role] = {
            "args":
            tmp_args,
            "action":
            subprocess.CompletedProcess(
                args=tmp_args,
                returncode=0,
                stdout=b'',
                stderr=b'',
            )
        }

    for role in ["calico_prefix", "adminrouter_prefix"]:
        tmp_args = base_args + ["role", "add", role]
        res["role_add_" + role] = {
            "args":
            tmp_args,
            "action":
            subprocess.CompletedProcess(
                args=tmp_args,
                returncode=0,
                stdout=b'',
                stderr=b'',
            )
        }

    for role_grant in [("root", "root"), ("calico", "calico_prefix"),
                       ("adminrouter", "adminrouter_prefix")]:
        tmp_args = base_args + [
            "user", "grant-role", role_grant[0], role_grant[1]
        ]
        res["role_grant_" + role_grant[0]] = {
            "args":
            tmp_args,
            "action":
            subprocess.CompletedProcess(
                args=tmp_args,
                returncode=0,
                stdout=b'',
                stderr=b'',
            )
        }

    for role_permission in [("calico_prefix", "/calico/"),
                            ("adminrouter_prefix", "/")]:
        tmp_args = base_args + [
            "role", "grant", role_permission[0], "--prefix=true", "readwrite",
            role_permission[1]
        ]
        res["role_permission_" + role_permission[0]] = {
            "args":
            tmp_args,
            "action":
            subprocess.CompletedProcess(
                args=tmp_args,
                returncode=0,
                stdout=b'',
                stderr=b'',
            )
        }

    for name in ["user", "role"]:
        tmp_args = base_args + [name, "list"]
        res[name + "_list"] = {
            "args":
            tmp_args,
            "action":
            subprocess.CompletedProcess(
                args=tmp_args,
                returncode=0,
                stdout=b'',
                stderr=b'',
            )
        }

    tmp_args = base_args + ["auth", "enable"]
    res["auth_enable"] = {
        "args":
        tmp_args,
        "action":
        subprocess.CompletedProcess(
            args=tmp_args,
            returncode=0,
            stdout=b'',
            stderr=b'',
        )
    }

    tmp_args = base_args + ["endpoint", "health"]
    res["endpoint_health"] = {
        "args":
        tmp_args,
        "action":
        subprocess.CompletedProcess(
            args=tmp_args,
            returncode=0,
            stdout=b'',
            stderr=b'',
        )
    }

    tmp_args = base_args + ["member", "list", "-w", "json"]
    res["member_list"] = {
        "args":
        tmp_args,
        "action":
        subprocess.CompletedProcess(
            args=tmp_args,
            returncode=0,
            stdout=b'''{
                         "header": {
                           "cluster_id": 2953241377848662500,
                           "member_id": 4079294043104093700,
                           "raft_term": 17
                         },
                         "members": [
                           {
                             "ID": 1301204472537744000,
                             "name": "etcd-1.1.1.1",
                             "peerURLs": [
                               "https://1.1.1.1:2380"
                             ],
                             "clientURLs": [
                               "http://1.1.1.1:2379",
                               "http://localhost:2379"
                             ]
                           }
                         ]
                       }
            ''',
            stderr=b'',
        )
    }

    tmp_args = base_args + [
        "member", "add", "etcd-1.2.3.4", "--peer-urls=https://1.2.3.4:2380"
    ]
    res["member_add"] = {
        "args":
        tmp_args,
        "action":
        subprocess.CompletedProcess(
            args=tmp_args,
            returncode=0,
            stdout=b'',
            stderr=b'',
        )
    }

    return res

def subprocess_sideeffect(call_data):
    def res(args, stdout, stderr):
        assert stdout is subprocess.PIPE
        assert stderr is subprocess.PIPE

        for k in call_data:
            if call_data[k]["args"] == args:
                return call_data[k]["action"]
        else:
            pytest.fail(
                "unhandled arguments have been passed: {}".format(args))

    return res

def complete_listener():

    class CompleteListener(OrderListener):

        def __init__(self):
            self.listened = False

        def on_complete(self, order: 'Order'):
