        if exchange.clock.step == 0:
            d = {
                ("USD", "BTC"): 7117.00,
                ("USD", "ETH"): 143.00,
                ("USD", "XRP"): 0.22
            }
            return d[(pair.base.symbol, pair.quote.symbol)]
        d = {
            ("USD", "BTC"): 6750.00,
            ("USD", "ETH"): 135.00,
            ("USD", "XRP"): 0.30
        }
        return d[(pair.base.symbol, pair.quote.symbol)]

    exchange.quote_price = mock.Mock(side_effect=quote_price)

    return exchange

