def gcon(request, ghandler):
    ip = request.config.getoption("--ip")
    port = request.config.getoption("--port")
    client = Milvus(host=ip, port=port, handler=ghandler)

    def fin():
        try:
            client.close()
            pass
        except Exception as e:
            print(e)
            pass

    request.addfinalizer(fin)
    return client

