    @Directive("actAsPyEnum", schema_name="test_issue_233")
    class ActAsPyEnumDirective:
        @staticmethod
        async def on_post_input_coercion(
            directive_args: Dict[str, Any],
            next_directive: Callable,
            parent_node,
            value: Any,
            ctx: Optional[Any],
        ):
            value = await next_directive(parent_node, value, ctx)
            if value is None:
                return value

            try:
                py_enum = _ENUM_MAP[directive_args["name"]]
                if isinstance(value, list):
                    return [
                        None if item is None else py_enum[item].value
                        for item in value
                    ]
                return py_enum[value].value
            except Exception:
                pass
            return value

        @staticmethod
        async def on_pre_output_coercion(
            directive_args: Dict[str, Any],
            next_directive: Callable,
            value: Any,
            ctx: Optional[Any],
            info: "ResolveInfo",
        ):
            value = await next_directive(value, ctx, info)
            if value is None:
                return value

            try:
                py_enum = _ENUM_MAP[directive_args["name"]]
                if isinstance(value, list):
                    return [
                        None if item is None else py_enum(item).name
                        for item in value
                    ]
                return py_enum(value).name
            except Exception:
                pass
            return value

