            next_resolver: Callable,
            parent: Optional[Any],
            args: Dict[str, Any],
            ctx: Optional[Any],
            info: "ResolveInfo",
        ) -> Any:
            result = await next_resolver(parent, args, ctx, info)
            if len(result) > directive_args["limit"]:
                raise Exception(
                    f"Value of field < {info.schema_field.name} is too long."
                )
            return result

