def simple_square_acquisition():
    class SimpleSquareAcquisition(Acquisition):
        def __init__(self):
            pass

        def evaluate(self, x):
            y = - x[:, 0]**2 + np.sum(x[:, 1:], axis=1) + 1
            return np.atleast_2d(y).T

        @property
        def has_gradients(self):
            return False

    return SimpleSquareAcquisition()

def trust_region_constr_linear_constraint():
    constraints = [LinearInequalityConstraint(np.array([[0, 1]]), np.array([0.5]), np.array([np.inf]))]
    return OptTrustRegionConstrained([(-1, 1), (-1, 1)], constraints, 1000)

def trust_region_constr_nonlinear_constraint():
    constraint_function = lambda x: (x[0] + x[1])**2
    constraints = [NonlinearInequalityConstraint(constraint_function, np.array([2.]), np.array([np.inf]))]
    return OptTrustRegionConstrained([(-1, 1), (-1, 1)], constraints, 1000)

def linear_constraint():
    A = np.array([[1., 0.5]])
    b_lower = np.array([-5])
    b_upper = np.array([5])
    return LinearInequalityConstraint(A, b_lower, b_upper)

def linear_constraint_2d():
    A = np.array([[1., 0.5], [0.5, 1.]])
    b_lower = np.array([-5, -5])
    b_upper = np.array([5, 5])
    return LinearInequalityConstraint(A, b_lower, b_upper)

