                                measurement_model=None, **kwargs):
            return GaussianMeasurementPrediction(state_prediction.state_vector,
                                                 state_prediction.covar,
                                                 state_prediction.timestamp)
    return TestGaussianUpdater()

def model():
    return CombinedReversibleGaussianMeasurementModel([
        CartesianToBearingRange(5, [0, 1], np.diag([1, 10])),
        CartesianToBearingRange(5, [3, 4], np.diag([2, 20])),
    ])

def transition_model1():
    class TestTransitionModel:
        def function(self, state, noise, time_interval):
            return state.state_vector + time_interval.total_seconds()
    return TestTransitionModel()

def transition_model2():
    class TestTransitionModel:
        def function(self, state, noise, time_interval):
            return state.state_vector + 2*time_interval.total_seconds()
    return TestTransitionModel()

def sensor_model1():
    class TestSensor(Sensor):

        def measure(self, ground_truths):
            detections = set()
            for truth in ground_truths:
                detections.add(Detection(truth.state_vector[(0, 2), :], timestamp=truth.timestamp))
            return detections
    return TestSensor()

def sensor_model2():
    class TestSensor(Sensor):

        def measure(self, ground_truths):
            detections = set()
            for truth in ground_truths:
                detections.add(Detection(truth.state_vector, timestamp=truth.timestamp))
            return detections
    return TestSensor()

def initiator():
    class TestInitiator:
        def initiate(self, unassociated_detections):
            return {Track([detection])
                    for detection in unassociated_detections}
    return TestInitiator()

def data_associator():
    class TestDataAssociator:
        def associate(self, tracks, detections, time):
            associations = {}
            for track in tracks:
                prediction = GaussianStatePrediction(track.state_vector + 1,
                                                     [[5]], time)
                measurement_prediction = StateMeasurementPrediction(
                    prediction.state_vector)
                for detection in detections:
                    if np.array_equal(measurement_prediction.state_vector,
                                      detection.state_vector):
                        associations[track] = \
                            SingleDistanceHypothesis(
                            prediction, detection, 0, measurement_prediction)
                        break
                else:
                    associations[track] = SingleDistanceHypothesis(
                        prediction, None, None, 1)
            return associations
    return TestDataAssociator()

def updater():
    class TestUpdater:
        def update(self, hypothesis):
            return GaussianStateUpdate(hypothesis.measurement.state_vector,
                                       hypothesis.prediction.covar,
                                       hypothesis,
                                       0)

        def predict_measurement(self, state_prediction,
                                measurement_model=None, **kwargs):
            return GaussianMeasurementPrediction(
                    state_prediction.state_vector,
                    state_prediction.covar,
                    state_prediction.timestamp)

    return TestUpdater()

def groundtruth_reader():
    class TestGroundTruthReader(GroundTruthReader):
        @BufferedGenerator.generator_method
        def groundtruth_paths_gen(self):
            time = datetime.datetime(2018, 1, 1, 14)
            state_vector = StateVector([[0]])
            for i in range(2):
                groundtruth_paths = {
                    GroundTruthPath(
                        [GroundTruthState(
                            state_vector + i + 10*j, timestamp=time)
                         for j in range(i)],
                        str(k))
                    for k in range(i)}
                yield time, groundtruth_paths
                time += datetime.timedelta(minutes=1)
    return TestGroundTruthReader()

def tracker():
    class TestTracker(Tracker):
        @BufferedGenerator.generator_method
        def tracks_gen(self):
            time = datetime.datetime(2018, 1, 1, 14)
            state_vector = StateVector([[0]])
            for i in range(2):
                tracks = {
                    Track(
                        [State(
                            state_vector + i + 10*j, timestamp=time)
                            for j in range(i)],
                        str(k))
                    for k in range(i)}
                yield time, tracks
                time += datetime.timedelta(minutes=1)
    return TestTracker()

def restore_working_directory(tmpdir, request):
    previous_cwd = os.getcwd()
    tmpdir.chdir()

    def return_to_previous():
        os.chdir(previous_cwd)

    request.addfinalizer(return_to_previous)

