def get_duress_secret(sim_eval):
    def doit(pin):
        # read the duress secret
        rv = sim_eval(f'main.pa.fetch(duress_pin=b"{pin}")', timeout=9000)
        if rv.startswith('Traceback'):
            raise RuntimeError(rv)
        assert rv[0:2] == "b'"
        return eval(rv)
    return doit

def readback_rule(sim_exec):
    # readback the stored config of a rule, after parsing
    def doit(idx):
        cmd = f"import ujson; from main import hsm_active; RV.write(ujson.dumps(hsm_active.rules[{idx}].to_json()));"
        txt = sim_exec(cmd)
        if 'Traceback' in txt:
            raise RuntimeError(txt)
        return json.loads(txt, object_hook=DICT)
    return doit

