                self.repo["pulp_href"] + "modify/", {"add_content_units": [content["pulp_href"]]}
            )
        self.repo = self.client.get(self.repo["pulp_href"])
        self.repo_version_hrefs = tuple(version["pulp_href"] for version in get_versions(self.repo))

