def setUp(self, startup_file: str = "file2.blend"):
        try:
            files_folder = Path(__file__).parent / "files"
            file = files_folder / startup_file
            blenderdesc = BlenderDesc(load_file=file)
            blenderdescs = [blenderdesc, BlenderDesc()]

            self.latency = 1
            latency_ms = 1000 * self.latency
            server_args = ["--latency", str(latency_ms)]
            super().setUp(blenderdescs=blenderdescs, server_args=server_args)
            if not self.vrtist_protocol:
                self.ignored_messages |= {
                    # TODO clarify this
                    MessageType.ADD_OBJECT_TO_VRTIST,
                    # set to the scene displayed, which is not important as VRtist supports one scene only
                    MessageType.SET_SCENE,
                }

        except Exception:
            self.shutdown()
            raise

def delayed_dask_stack():
    """A 4D (20, 10, 10, 10) delayed dask array, simulates disk io."""
    # we will return a dict with a 'calls' variable that tracks call count
    output = {'calls': 0}

    # create a delayed version of function that simply generates np.arrays
    # but also counts when it has been called
    @dask.delayed
    def get_array():
        nonlocal output
        output['calls'] += 1
        return np.random.rand(10, 10, 10)

    # then make a mock "timelapse" of 3D stacks
    # see https://napari.org/tutorials/applications/dask.html for details
    _list = [get_array() for fn in range(20)]
    output['stack'] = da.stack(
        [da.from_delayed(i, shape=(10, 10, 10), dtype=np.float) for i in _list]
    )
    assert output['stack'].shape == (20, 10, 10, 10)
    return output

def make_test_viewer(qtbot, request):
    viewers: List[Viewer] = []

    def actual_factory(*model_args, viewer_class=Viewer, **model_kwargs):
        model_kwargs['show'] = model_kwargs.pop(
            'show', request.config.getoption("--show-viewer")
        )
        viewer = viewer_class(*model_args, **model_kwargs)
        viewers.append(viewer)
        return viewer

    yield actual_factory

    for viewer in viewers:
        viewer.close()

def perfmon_only(request):
    """If flag is set, only run the perfmon tests."""
    perfmon_flag = request.config.getoption("--perfmon-only")
    perfmon_test = request.node.get_closest_marker('perfmon')
    if perfmon_flag and not perfmon_test:
        pytest.skip("running with --perfmon-only")
    if not perfmon_flag and perfmon_test:
        pytest.skip("not running with --perfmon-only")

