def fncDir(tmpDir):
    """A temporary folder for a single test function.
    """
    fncDir = os.path.join(tmpDir, "f_temp")
    if os.path.isdir(fncDir):
        shutil.rmtree(fncDir)
    if not os.path.isdir(fncDir):
        os.mkdir(fncDir)
    yield fncDir
    if os.path.isdir(fncDir):
        shutil.rmtree(fncDir)
    return

