def widget_size():
    """
    Returns widget size for any widget.
    """
    def _widget_size(widget):
        widget_type, *_ = widget.sizing()
        if widget_type == 'box':
            return (200, 20)
        elif widget_type == 'flow':
            return (20, )
        else:
            None

    return _widget_size

