def example_graph_schema():
    def create_schema(aa=1, ab=1, ba=1, bb=1):
        # graph schema
        schema = {"A": [], "B": []}
        for ii in range(aa):
            schema["A"].append(EdgeType("A", "a%d" % ii, "A"))
        for ii in range(ab):
            schema["A"].append(EdgeType("A", "ab%d" % ii, "B"))
        for ii in range(ba):
            schema["B"].append(EdgeType("B", "ab%d" % ii, "A"))
        for ii in range(bb):
            schema["B"].append(EdgeType("B", "b%d" % ii, "B"))

        return GraphSchema(
            is_directed=False,
            node_types=sorted(schema.keys()),
            edge_types=sorted(set(it.chain(*schema.values()))),
            schema=schema,
        )

    return create_schema

def arange_graph(request):
    shape = (3, 7, 11) if request.param == "multivariate" else (3, 7)
    total_elems = np.product(shape)
    nodes = IndexedArray(
        np.arange(total_elems).reshape(shape) / total_elems, index=["a", "b", "c"]
    )
    edges = pd.DataFrame({"source": ["a", "b"], "target": ["b", "c"]})
    return StellarGraph(nodes, edges)

def petersen_graph() -> StellarGraph:
    nxg = nx.petersen_graph()
    return StellarGraph.from_networkx(nxg, node_features=node_features())

def cli_args(openapi_version, request):
    if request.param == "real":
        schema_url = request.getfixturevalue("schema_url")
        args = (schema_url,)
    else:
        app_path = request.getfixturevalue("loadable_flask_app")
        args = (f"--app={app_path}", "/schema.yaml")
    return args

def new_check(request, testdir, cli):
    exception, message = request.param
    module = testdir.make_importable_pyfile(
        hook=f"""
            import schemathesis

            @schemathesis.register_check
            def new_check(response, result):
                raise {exception}
            """
    )
    yield module, message
    reset_checks()
    # To verify that "new_check" is unregistered
    result = cli.run("--help")
    lines = result.stdout.splitlines()
    assert (
        "  -c, --checks [not_a_server_error|status_code_conformance|content_type_conformance|"
        "response_headers_conformance|response_schema_conformance|all]" in lines
    )

