def onnx_repo_models(request) -> OnnxRepoModelFixture:
    model_args, model_name = request.param
    model = RepoModel(**model_args)
    model_path = model.download_onnx_file(overwrite=False)
    data_paths = model.download_data_files(overwrite=False)

    input_paths = None
    output_paths = None
    for path in data_paths:
        if "_sample-inputs" in path:
            input_paths = path.split(".tar")[0]
        elif "_sample-outputs" in path:
            output_paths = path.split(".tar")[0]
    return OnnxRepoModelFixture(model_path, model_name, input_paths, output_paths)

def node_info(request) -> NodeInfoFixture:
    node_dict, loss_result, perf_result, loss_bucket, perf_bucket = request.param
    node = NodeAnalyzer(None, None, **node_dict)
    loss_result = PruningSensitivityResult.from_dict(loss_result)
    perf_result = PruningSensitivityResult.from_dict(perf_result)
    return NodeInfoFixture(node, loss_result, perf_result, loss_bucket, perf_bucket)

def dataloader_models(request) -> DataloaderModelFixture:
    model_args, input_shapes, output_shapes, data_types = request.param
    model = RepoModel(**model_args)
    model_path = model.download_onnx_file(overwrite=False)

    return DataloaderModelFixture(model_path, input_shapes, output_shapes, data_types)

