def kill_own_pid():
    def f(signal=stdlib_signal.SIGTERM):
        os.kill(os.getpid(), signal)

    return f

def app(not_opened_app):
    with not_opened_app.open() as app:
        yield app

def job_factory(serial, random_str):
    def factory(**kwargs):
        defaults = {
            "id": next(serial),
            "task_name": f"task_{random_str()}",
            "task_kwargs": {},
            "lock": str(uuid.uuid4()),
            "queueing_lock": None,
            "queue": f"queue_{random_str()}",
        }
        final_kwargs = defaults.copy()
        final_kwargs.update(kwargs)
        return jobs.Job(**final_kwargs)

    return factory

def entrypoint(cli_runner):
    def ep(args=""):
        # basicConfig works better if handlers config is properly isolated
        logging.getLogger("").handlers = []
        return cli_runner.invoke(cli.cli, args.split(), catch_exceptions=False)

    logging.getLogger("").handlers = []
    return ep

