def kernel():
    installed_kernels = [
        x.split(" ")[0]
        for x in [
            re.sub("  +", " ", x.strip(" "))
            for x in filter(
                lambda x: x.startswith("  "),
                subprocess.check_output(["jupyter", "kernelspec", "list"])
                .decode("utf-8")
                .split("\n"),
            )
        ]
    ]
    if "dagster" not in installed_kernels:
        warnings.warn(
            'Jupyter kernel "dagster" not found, installing. Don\'t worry, this is noninvasive '
            "and you can reverse it by running `jupyter kernelspec uninstall dagster`."
        )
        subprocess.check_output(["ipython", "kernel", "install", "--name", "dagster", "--user"])

def basic_lakehouse_and_storages():
    storage1 = DictStorage()
    storage2 = DictStorage()

    @resource()
    def some_storage(_):
        return storage1

    @resource()
    def some_other_storage(_):
        return storage2

    dev_mode = ModeDefinition(
        name="dev", resource_defs={"storage1": some_storage, "storage2": some_other_storage},
    )
    dev_preset = PresetDefinition(name="dev", mode="dev", run_config={}, solid_selection=None)

    return (
        Lakehouse(mode_defs=[dev_mode], preset_defs=[dev_preset]),
        storage1,
        storage2,
    )

