def linters(lintdir, request):
    suffix_filter = getattr(request.module, 'linters', ['.lint.py'])
    return [os.path.join(lintdir, p) for p in os.listdir(lintdir)
            if any(p.endswith(suffix) for suffix in suffix_filter)]

def run(parser, lintdir, files):
    if lintdir not in cli.SEARCH_PATHS:
        cli.SEARCH_PATHS.append(lintdir)

    def inner(args=None):
        args = args or []
        args.extend(files)
        lintargs = vars(parser.parse_args(args))
        lintargs['root'] = here
        return cli.run(**lintargs)
    return inner

