def hge_ctx(request):
    config = request.config
    print("create hge_ctx")
    if is_master(config):
        hge_url = config.hge_url_list[0]
    else:
        hge_url = config.slaveinput["hge-url"]

    if is_master(config):
        pg_url = config.pg_url_list[0]
    else:
        pg_url = config.slaveinput["pg-url"]

    try:
        hge_ctx = HGECtx(hge_url, pg_url, config)
    except HGECtxError as e:
        assert False, "Error from hge_cxt: " + str(e)
        # TODO this breaks things (https://github.com/pytest-dev/pytest-xdist/issues/86)
        #      so at least make sure the real error gets printed (above)
        pytest.exit(str(e))
    yield hge_ctx  # provide the fixture value
    print("teardown hge_ctx")
    hge_ctx.teardown()
    time.sleep(1)

def isolate_packages_cache(tmp_path):
    with mock.patch('quilt3.packages.CACHE_PATH', tmp_path):
        yield

def setUp(self):
        """
        Mocks to tests calls to S3 Select
        """

        def make_s3response(bytes):
            return {
                'Payload': [
                    {
                        'Records': {
                            'Payload': bytes
                        }
                    },
                    {
                        'Progress': {
                            'Details': {
                                'BytesScanned': 123,
                                'BytesProcessed': 123,
                                'BytesReturned': 123
                            }
                        }
                    },
                    {
                        'Stats': {
                            'Details': {
                                'BytesScanned': 123,
                                'BytesProcessed': 123,
                                'BytesReturned': 123
                            }
                        }
                    },
                    {
                        'End': {}
                    }
                ]
            }

        logical_keys = [
            "foo.csv",
            "bar/file1.txt",
            "bar/file2.txt",
            "bar/baz/file3.txt",
            "bar/baz/file4.txt"
        ]
        entries = []
        for key in logical_keys:
            entry = dict(
                logical_key=key,
                physical_key=f"{key}?versionid=1234",
                size=100
            )
            entries.append(json.dumps(entry))
        jsonl = "\n".join(entries)
        print(jsonl)
        streambytes = jsonl.encode()

        manifest_row = dict(
            logical_key="bar/file1.txt",
            physical_keys=["s3://test-bucket/bar/file1.txt"],
            size=1234,
            hash={"type": "SHA256", "value": "0123456789ABCDEF"},
            meta={}
        )
        detailbytes = json.dumps(manifest_row).encode()
        self.s3response = make_s3response(streambytes)
        self.s3response_detail = make_s3response(detailbytes)
        self.s3response_incomplete = {
            'Payload': [
                {
                    'Records': {
                        'Payload': streambytes
                    }
                },
                {
                    'Stats': {
                        'Details': {
                            'BytesScanned': 123,
                            'BytesProcessed': 123,
                            'BytesReturned': 123
                        }
                    }
                }
            ]
        }

        meta = {
            "version": "v0",
            "user_meta": {
                "somefield": "somevalue"
            },
            "message": "Commit message"
        }
        metabytes = json.dumps(meta).encode()
        self.s3response_meta = make_s3response(metabytes)

        requests_mock = responses.RequestsMock(assert_all_requests_are_fired=False)
        requests_mock.start()
        self.addCleanup(requests_mock.stop)

        env_patcher = patch.dict(os.environ, {
            'AWS_ACCESS_KEY_ID': 'test_key',
            'AWS_SECRET_ACCESS_KEY': 'test_secret',
        })
        env_patcher.start()
        self.addCleanup(env_patcher.stop)

def tearDown(self):
        self.env_patcher.stop()
        self.requests_mock.stop()

